// Precios USD por millón de tokens: verificar en groq.com/pricing.
const PRECIOS={A:[0.075,0.30],B:[0.15,0.60],juez:[0.15,0.60]};
let rows=[];for(let i=0;i<5;i++){for(const x of $('[E0] Resultado de pregunta').all(0,i))for(const r of x.json.resultados||[])if(r.origen==='qa_ab'&&String(r.traceId).startsWith($execution.id+'-qa-'))rows.push(r)}
if(rows.length!==10)throw new Error('QA incompleto: '+rows.length+' filas, se esperaban 10');const stats={};for(const a of ['A','B']){const r=rows.filter(x=>x.arquitectura===a);if(r.length!==5)throw new Error('Faltan resultados de '+a);const cat={};for(const x of r)cat[x.categoria_error]=(cat[x.categoria_error]||0)+1;const avg=k=>r.reduce((s,x)=>s+Number(x[k]||0),0)/r.length;stats[a]={precision_media:avg('exactitud'),porcentaje_aprobado:100*r.filter(x=>x.veredicto==='APROBADO').length/r.length,errores:cat,latencia_media_ms:avg('latencia_ms'),tokens_medios_entrada:avg('tokens_entrada'),tokens_medios_salida:avg('tokens_salida'),costo_1000_usd:avg('costo_usd')*1000};}const a=stats.A,b=stats.B;const best=(a.precision_media/(a.costo_1000_usd||1e-9)>=b.precision_media/(b.costo_1000_usd||1e-9))?'A':'B';const resumen='QA A/B · corrida '+$execution.id+'\n'+['A','B'].map(k=>{const s=stats[k];return k+': exactitud '+s.precision_media.toFixed(2)+'/5; aprobados '+s.porcentaje_aprobado.toFixed(0)+'%; categorías '+JSON.stringify(s.errores)+'; latencia '+Math.round(s.latencia_media_ms)+' ms; costo/1000 USD '+s.costo_1000_usd.toFixed(4)}).join('\n')+'\nRecomendación: '+best+' por mejor relación exactitud/costo entre las muestras. Costos de respuesta reales y juez estimado; muestra de 5 por arquitectura.';return [{json:{stats,recomendacion:best,resumen,filas:rows.length}}];
